-- Pocket-style Building Management System schema (initial safe migration)
-- Run only in a NEW Supabase project. This script does not drop or truncate data.
-- Before production: test with separate Owner/Admin/Resident accounts and review RLS.
begin;
create extension if not exists pgcrypto;
do $$ begin create type public.bms_role as enum ('owner','admin','resident'); exception when duplicate_object then null; end $$;
do $$ begin create type public.review_status as enum ('pending','approved','rejected','voided'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,display_name text not null default '',created_at timestamptz not null default now());
create table if not exists public.buildings(id uuid primary key default gen_random_uuid(),name text not null,address text not null default '',unit_count integer not null default 0 check(unit_count>=0),monthly_fee numeric(12,2) not null default 0 check(monthly_fee>=0),created_at timestamptz not null default now());
create table if not exists public.building_members(id uuid primary key default gen_random_uuid(),building_id uuid not null references public.buildings(id),user_id uuid not null references public.profiles(id),role public.bms_role not null check(role in ('owner','admin')),created_at timestamptz not null default now(),unique(building_id,user_id));
create table if not exists public.apartments(id uuid primary key default gen_random_uuid(),building_id uuid not null references public.buildings(id),unit_number text not null,resident_name text not null default '',monthly_fee numeric(12,2) not null default 0 check(monthly_fee>=0),created_at timestamptz not null default now(),unique(building_id,unit_number));
create table if not exists public.apartment_residents(id uuid primary key default gen_random_uuid(),apartment_id uuid not null references public.apartments(id),user_id uuid not null references public.profiles(id),status public.review_status not null default 'pending',requested_at timestamptz not null default now(),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,unique(apartment_id,user_id));
create unique index if not exists one_active_resident_per_apartment on public.apartment_residents(apartment_id) where status='approved';
create table if not exists public.monthly_dues(id uuid primary key default gen_random_uuid(),apartment_id uuid not null references public.apartments(id),period date not null,amount_due numeric(12,2) not null check(amount_due>=0),created_at timestamptz not null default now(),unique(apartment_id,period));
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),building_id uuid not null references public.buildings(id),apartment_id uuid not null references public.apartments(id),amount numeric(12,2) not null check(amount>0),paid_at date not null default current_date,method text not null default 'cash',status public.review_status not null default 'pending',created_by uuid not null references public.profiles(id),approved_by uuid references public.profiles(id),approved_at timestamptz,notes text not null default '',created_at timestamptz not null default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),building_id uuid not null references public.buildings(id),title text not null,category text not null default 'other',amount numeric(12,2) not null check(amount>0),spent_at date not null default current_date,status public.review_status not null default 'pending',created_by uuid not null references public.profiles(id),approved_by uuid references public.profiles(id),approved_at timestamptz,notes text not null default '',created_at timestamptz not null default now());
create table if not exists public.treasury_transactions(id uuid primary key default gen_random_uuid(),building_id uuid not null references public.buildings(id),source_type text not null check(source_type in ('payment','expense','adjustment')),source_id uuid not null,amount numeric(12,2) not null check(amount<>0),posted_at timestamptz not null default now(),posted_by uuid not null references public.profiles(id),unique(source_type,source_id));
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),building_id uuid references public.buildings(id),actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.is_owner() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from building_members where user_id=auth.uid() and role='owner') $$;
create or replace function public.can_manage_building(bid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from building_members where user_id=auth.uid() and building_id=bid and role in ('owner','admin')) $$;
create or replace function public.can_view_building(bid uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.can_manage_building(bid) or exists(select 1 from apartment_residents ar join apartments a on a.id=ar.apartment_id where ar.user_id=auth.uid() and ar.status='approved' and a.building_id=bid) $$;
alter table public.profiles enable row level security; alter table public.buildings enable row level security; alter table public.building_members enable row level security; alter table public.apartments enable row level security; alter table public.apartment_residents enable row level security; alter table public.monthly_dues enable row level security; alter table public.payments enable row level security; alter table public.expenses enable row level security; alter table public.treasury_transactions enable row level security; alter table public.audit_logs enable row level security;
drop policy if exists profiles_read_self on public.profiles; create policy profiles_read_self on public.profiles for select to authenticated using(id=auth.uid() or public.is_owner());
drop policy if exists buildings_read_members on public.buildings; create policy buildings_read_members on public.buildings for select to authenticated using(public.can_view_building(id));
drop policy if exists buildings_owner_all on public.buildings; create policy buildings_owner_all on public.buildings for all to authenticated using(public.is_owner()) with check(public.is_owner());
drop policy if exists members_read_scope on public.building_members; create policy members_read_scope on public.building_members for select to authenticated using(user_id=auth.uid() or public.can_manage_building(building_id));
drop policy if exists apartments_read_scope on public.apartments; create policy apartments_read_scope on public.apartments for select to authenticated using(public.can_manage_building(building_id) or exists(select 1 from apartment_residents ar where ar.apartment_id=id and ar.user_id=auth.uid() and ar.status='approved'));
drop policy if exists apartments_manage_admin on public.apartments; create policy apartments_manage_admin on public.apartments for all to authenticated using(public.can_manage_building(building_id)) with check(public.can_manage_building(building_id));
drop policy if exists resident_links_read_scope on public.apartment_residents; create policy resident_links_read_scope on public.apartment_residents for select to authenticated using(user_id=auth.uid() or exists(select 1 from apartments a where a.id=apartment_id and public.can_manage_building(a.building_id)));
drop policy if exists resident_link_request on public.apartment_residents; create policy resident_link_request on public.apartment_residents for insert to authenticated with check(user_id=auth.uid() and status='pending');
drop policy if exists resident_link_review on public.apartment_residents; create policy resident_link_review on public.apartment_residents for update to authenticated using(exists(select 1 from apartments a where a.id=apartment_id and public.can_manage_building(a.building_id))) with check(exists(select 1 from apartments a where a.id=apartment_id and public.can_manage_building(a.building_id)));
drop policy if exists dues_read_scope on public.monthly_dues; create policy dues_read_scope on public.monthly_dues for select to authenticated using(exists(select 1 from apartments a where a.id=apartment_id and (public.can_manage_building(a.building_id) or exists(select 1 from apartment_residents ar where ar.apartment_id=a.id and ar.user_id=auth.uid() and ar.status='approved'))));
drop policy if exists dues_manage_admin on public.monthly_dues; create policy dues_manage_admin on public.monthly_dues for all to authenticated using(exists(select 1 from apartments a where a.id=apartment_id and public.can_manage_building(a.building_id))) with check(exists(select 1 from apartments a where a.id=apartment_id and public.can_manage_building(a.building_id)));
drop policy if exists payments_read_scope on public.payments; create policy payments_read_scope on public.payments for select to authenticated using(public.can_manage_building(building_id) or exists(select 1 from apartment_residents ar where ar.apartment_id=payments.apartment_id and ar.user_id=auth.uid() and ar.status='approved'));
drop policy if exists payments_create_admin on public.payments; create policy payments_create_admin on public.payments for insert to authenticated with check(public.can_manage_building(building_id) and created_by=auth.uid() and status='pending');
drop policy if exists payments_owner_approve on public.payments; create policy payments_owner_approve on public.payments for update to authenticated using(public.is_owner()) with check(public.is_owner());
drop policy if exists expenses_read_admin on public.expenses; create policy expenses_read_admin on public.expenses for select to authenticated using(public.can_manage_building(building_id));
drop policy if exists expenses_create_admin on public.expenses; create policy expenses_create_admin on public.expenses for insert to authenticated with check(public.can_manage_building(building_id) and created_by=auth.uid() and status='pending');
drop policy if exists expenses_owner_approve on public.expenses; create policy expenses_owner_approve on public.expenses for update to authenticated using(public.is_owner()) with check(public.is_owner());
drop policy if exists treasury_read_admin on public.treasury_transactions; create policy treasury_read_admin on public.treasury_transactions for select to authenticated using(public.can_manage_building(building_id));
drop policy if exists audit_read_admin on public.audit_logs; create policy audit_read_admin on public.audit_logs for select to authenticated using(building_id is not null and public.can_manage_building(building_id));
commit;
-- IMPORTANT: this schema intentionally does not auto-post approved operations to the ledger.
-- Implement approval + ledger posting in a single reviewed SECURITY DEFINER RPC before production.
